import Foundation
import Testing
import WingcordCore
@testable import WingcordNet

/// SET_ACTIVITY as Discord's handler takes it: its Joi schema's sentences, and
/// what it does to an activity that passes.
///
/// **The sentences are Joi's own**, generated by running Discord's bundled Joi
/// (`88137`) on Discord's schema in Node — never written from reading the
/// templates. Discord sends them back to the app verbatim.
@Suite("Local RPC activity")
struct LocalRPCActivityTests {

    /// (case, the args as JSON, Joi's message or nil for a pass).
    static let joi: [(String, String, String?)] = [
        (#"valid"#, #"{"pid":42,"activity":{"state":"In a match","details":"Ranked","timestamps":{"start":1700000000},"assets":{"large_image":"map","large_text":"Dust II"},"buttons":[{"label":"Watch","url":"https://example.com"}],"type":0}}"#, nil),
        (#"valid null"#, #"{"pid":42,"activity":null}"#, nil),
        (#"valid unknown keys"#, #"{"pid":42,"activity":{"state":"ok state","whatever":1},"extra":true}"#, nil),
        (#"missing args"#, #"null"#, #""value" must be an object"#),
        (#"args not object"#, #""x""#, #""value" must be an object"#),
        (#"pid negative"#, #"{"pid":-1,"activity":null}"#, #"child "pid" fails because ["pid" must be larger than or equal to 0]"#),
        (#"pid string"#, #"{"pid":"42","activity":null}"#, #"child "pid" fails because ["pid" must be a number]"#),
        (#"state short"#, #"{"pid":1,"activity":{"state":"x"}}"#, #"child "activity" fails because [child "state" fails because ["state" length must be at least 2 characters long]]"#),
        (#"state long"#, #"{"pid":1,"activity":{"state":"xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"}}"#, #"child "activity" fails because [child "state" fails because ["state" length must be less than or equal to 128 characters long]]"#),
        (#"details not string"#, #"{"pid":1,"activity":{"details":5}}"#, #"child "activity" fails because [child "details" fails because ["details" must be a string]]"#),
        (#"name empty"#, #"{"pid":1,"activity":{"name":""}}"#, #"child "activity" fails because [child "name" fails because ["name" is not allowed to be empty]]"#),
        (#"state_url bad"#, #"{"pid":1,"activity":{"state_url":"not a url"}}"#, #"child "activity" fails because [child "state_url" fails because ["state_url" must be a valid uri]]"#),
        (#"timestamps start zero"#, #"{"pid":1,"activity":{"timestamps":{"start":0}}}"#, #"child "activity" fails because [child "timestamps" fails because [child "start" fails because ["start" must be larger than or equal to 1]]]"#),
        (#"timestamps not object"#, #"{"pid":1,"activity":{"timestamps":5}}"#, #"child "activity" fails because [child "timestamps" fails because ["timestamps" must be an object]]"#),
        (#"large_text short"#, #"{"pid":1,"activity":{"assets":{"large_text":"a"}}}"#, #"child "activity" fails because [child "assets" fails because [child "large_text" fails because ["large_text" length must be at least 2 characters long]]]"#),
        (#"party size 3"#, #"{"pid":1,"activity":{"party":{"size":[1,2,3]}}}"#, #"child "activity" fails because [child "party" fails because [child "size" fails because ["size" must contain 2 items]]]"#),
        (#"party size negative"#, #"{"pid":1,"activity":{"party":{"size":[-1,2]}}}"#, #"child "activity" fails because [child "party" fails because [child "size" fails because ["size" at position 0 fails because ["0" must be larger than or equal to 0]]]]"#),
        (#"party privacy 2"#, #"{"pid":1,"activity":{"party":{"privacy":2}}}"#, #"child "activity" fails because [child "party" fails because [child "privacy" fails because ["privacy" must be one of [0, 1]]]]"#),
        (#"buttons empty"#, #"{"pid":1,"activity":{"buttons":[]}}"#, #"child "activity" fails because [child "buttons" fails because ["buttons" must contain at least 1 items]]"#),
        (#"buttons three"#, #"{"pid":1,"activity":{"buttons":[{"label":"a","url":"https://a.com"},{"label":"b","url":"https://b.com"},{"label":"c","url":"https://c.com"}]}}"#, #"child "activity" fails because [child "buttons" fails because ["buttons" must contain less than or equal to 2 items]]"#),
        (#"button label long"#, #"{"pid":1,"activity":{"buttons":[{"label":"a very long button label that runs on","url":"https://a.com"}]}}"#, #"child "activity" fails because [child "buttons" fails because ["buttons" at position 0 fails because [child "label" fails because ["label" length must be less than or equal to 32 characters long]]]]"#),
        (#"button missing url"#, #"{"pid":1,"activity":{"buttons":[{"label":"a"}]}}"#, #"child "activity" fails because [child "buttons" fails because ["buttons" at position 0 fails because [child "url" fails because ["url" is required]]]]"#),
        (#"button url bad"#, #"{"pid":1,"activity":{"buttons":[{"label":"a","url":"nope"}]}}"#, #"child "activity" fails because [child "buttons" fails because ["buttons" at position 0 fails because [child "url" fails because ["url" must be a valid uri]]]]"#),
        (#"type 1"#, #"{"pid":1,"activity":{"type":1}}"#, #"child "activity" fails because [child "type" fails because ["type" must be one of [0, 2, 3, 5]]]"#),
        (#"type string"#, #"{"pid":1,"activity":{"type":"0"}}"#, #"child "activity" fails because [child "type" fails because ["type" must be a number]]"#),
        (#"status display 3"#, #"{"pid":1,"activity":{"status_display_type":3}}"#, #"child "activity" fails because [child "status_display_type" fails because ["status_display_type" must be one of [0, 1, 2]]]"#),
        (#"instance string"#, #"{"pid":1,"activity":{"instance":"yes"}}"#, #"child "activity" fails because [child "instance" fails because ["instance" must be a boolean]]"#),
        (#"platforms empty"#, #"{"pid":1,"activity":{"supported_platforms":[]}}"#, #"child "activity" fails because [child "supported_platforms" fails because ["supported_platforms" must contain at least 1 items]]"#),
        (#"secrets join short"#, #"{"pid":1,"activity":{"secrets":{"join":"a"}}}"#, #"child "activity" fails because [child "secrets" fails because [child "join" fails because ["join" length must be at least 2 characters long]]]"#),
        (#"activity array"#, #"{"pid":1,"activity":[1]}"#, #"child "activity" fails because ["activity" must be an object]"#),
        (#"two problems"#, #"{"pid":1,"activity":{"state":"x","details":"y"}}"#, #"child "activity" fails because [child "state" fails because ["state" length must be at least 2 characters long]]"#),
        (#"payload order"#, #"{"pid":1,"activity":{"details":"y","state":"x"}}"#, #"child "activity" fails because [child "state" fails because ["state" length must be at least 2 characters long]]"#),
        (#"pid after activity"#, #"{"activity":{"state":"x"},"pid":-1}"#, #"child "pid" fails because ["pid" must be larger than or equal to 0]"#),
        (#"no pid"#, #"{"activity":{"state":"ok!"}}"#, nil),
        (#"uri example.com"#, #"{"pid":1,"activity":{"state_url":"example.com"}}"#, #"child "activity" fails because [child "state_url" fails because ["state_url" must be a valid uri]]"#),
        (#"uri mailto"#, #"{"pid":1,"activity":{"state_url":"mailto:x@y.z"}}"#, nil),
        (#"uri space"#, #"{"pid":1,"activity":{"state_url":"https://ex ample.com"}}"#, #"child "activity" fails because [child "state_url" fails because ["state_url" must be a valid uri]]"#),
        (#"uri steam"#, #"{"pid":1,"activity":{"state_url":"steam://run/730"}}"#, nil),
        (#"uri http only"#, #"{"pid":1,"activity":{"state_url":"http://"}}"#, nil),
        (#"uri query"#, #"{"pid":1,"activity":{"state_url":"https://a.com/p?q=1#f"}}"#, nil),
        (#"uri unicode"#, #"{"pid":1,"activity":{"state_url":"https://exämple.com/ü"}}"#, #"child "activity" fails because [child "state_url" fails because ["state_url" must be a valid uri]]"#),
        (#"uri long"#, #"{"pid":1,"activity":{"state_url":"https://a.com/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}"#, #"child "activity" fails because [child "state_url" fails because ["state_url" length must be less than or equal to 256 characters long]]"#),
        (#"size both"#, #"{"pid":1,"activity":{"party":{"size":[-1,2,3]}}}"#, #"child "activity" fails because [child "party" fails because [child "size" fails because ["size" at position 0 fails because ["0" must be larger than or equal to 0]]]]"#),
        (#"size not array"#, #"{"pid":1,"activity":{"party":{"size":5}}}"#, #"child "activity" fails because [child "party" fails because [child "size" fails because ["size" must be an array]]]"#),
        (#"size string item"#, #"{"pid":1,"activity":{"party":{"size":["1",2]}}}"#, #"child "activity" fails because [child "party" fails because [child "size" fails because ["size" at position 0 fails because ["0" must be a number]]]]"#),
        (#"button not object"#, #"{"pid":1,"activity":{"buttons":["x"]}}"#, #"child "activity" fails because [child "buttons" fails because ["buttons" at position 0 fails because ["0" must be an object]]]"#),
        (#"buttons both"#, #"{"pid":1,"activity":{"buttons":[{"label":"","url":"https://a.com"},{"label":"b","url":"https://b.com"},{"label":"c","url":"https://c.com"}]}}"#, #"child "activity" fails because [child "buttons" fails because ["buttons" at position 0 fails because [child "label" fails because ["label" is not allowed to be empty]]]]"#),
        (#"label empty"#, #"{"pid":1,"activity":{"buttons":[{"label":"","url":"https://a.com"}]}}"#, #"child "activity" fails because [child "buttons" fails because ["buttons" at position 0 fails because [child "label" fails because ["label" is not allowed to be empty]]]]"#),
        (#"state empty"#, #"{"pid":1,"activity":{"state":""}}"#, #"child "activity" fails because [child "state" fails because ["state" is not allowed to be empty]]"#),
        (#"large_image empty"#, #"{"pid":1,"activity":{"assets":{"large_image":""}}}"#, #"child "activity" fails because [child "assets" fails because [child "large_image" fails because ["large_image" is not allowed to be empty]]]"#),
        (#"state null"#, #"{"pid":1,"activity":{"state":null}}"#, #"child "activity" fails because [child "state" fails because ["state" must be a string]]"#),
        (#"timestamps float"#, #"{"pid":1,"activity":{"timestamps":{"start":0.5}}}"#, #"child "activity" fails because [child "timestamps" fails because [child "start" fails because ["start" must be larger than or equal to 1]]]"#),
        (#"pid float"#, #"{"pid":1.5,"activity":null}"#, nil),
        (#"pid null"#, #"{"pid":null,"activity":null}"#, #"child "pid" fails because ["pid" must be a number]"#),
        (#"emoji state"#, #"{"pid":1,"activity":{"state":"😀"}}"#, nil),
        (#"state 128 emoji"#, #"{"pid":1,"activity":{"state":"😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀"}}"#, nil),
    ]

    @Test("Every case gets Joi's own sentence", arguments: joi)
    func joiSentence(_ fixture: (String, String, String?)) throws {
        let args = try #require(RPCValue(json: Data(fixture.1.utf8)), "\(fixture.0) is not JSON")
        #expect(LocalRPCSchema.setActivity.failure(of: args) == fixture.2, "\(fixture.0)")
    }

    @Test("No args at all is Joi's \"value\" is required")
    func absentArgs() {
        #expect(LocalRPCSchema.setActivity.failure(of: nil) == #""value" is required"#)
    }

    private let app = (id: ApplicationID(rawValue: 383226320973907245), name: "Visual Studio Code")
    private let now = Date(timeIntervalSince1970: 1_800_000_000)

    private func request(_ json: String, requiresPID: Bool = true, friends: Bool = true, voice: Bool = true)
        throws -> LocalRPCActivityRequest {
        try LocalRPCActivityRequest(
            args: RPCValue(json: Data(json.utf8)),
            application: app,
            requiresPID: requiresPID,
            partyPrivacy: (friends, voice),
            now: now
        )
    }

    @Test("An activity without a name takes its app's, and a button's link goes to metadata")
    func shaping() throws {
        let made = try request(#"""
        {"pid":7,"activity":{"state":"Editing x.swift","details":"In wingcord",
         "buttons":[{"label":"Repo","url":"https://example.com/repo"}],"status_display_type":2}}
        """#)
        let activity = try #require(made.activity)
        #expect(made.pid == 7)
        #expect(activity.name == "Visual Studio Code")
        #expect(activity.type == 0)
        #expect(activity.applicationID == app.id)
        #expect(activity.buttons == ["Repo"])
        #expect(activity.buttonURLs == [URL(string: "https://example.com/repo")!])
        #expect(activity.statusDisplayType == 2)
        #expect(activity.flags == 0)
    }

    /// Discord's rule: more than two digits shorter than `Date.now()` is
    /// seconds.
    @Test("Seconds become milliseconds, milliseconds stay")
    func seconds() throws {
        let seconds = try #require(try request(#"{"pid":1,"activity":{"timestamps":{"start":1700000000,"end":1700000000123}}}"#).activity)
        #expect(seconds.timestamps?.start == 1_700_000_000_000)
        #expect(seconds.timestamps?.end == 1_700_000_000_123)
        // Eleven digits is two short of thirteen: not seconds, by Discord's count.
        let eleven = try #require(try request(#"{"pid":1,"activity":{"timestamps":{"start":17000000000}}}"#).activity)
        #expect(eleven.timestamps?.start == 17_000_000_000)
    }

    @Test("An instance is flagged; a public party carries who may join")
    func flags() throws {
        #expect(try request(#"{"pid":1,"activity":{"instance":true}}"#).activity?.flags == 1)
        #expect(try request(#"{"pid":1,"activity":{"party":{"id":"pp","privacy":1}}}"#).activity?.flags == 192)
        #expect(try request(#"{"pid":1,"activity":{"party":{"id":"pp","privacy":1}}}"#, friends: false).activity?.flags == 128)
        #expect(try request(#"{"pid":1,"activity":{"party":{"id":"pp","privacy":0}}}"#).activity?.flags == 0)
    }

    @Test("Discord's secret rules, each with its own words")
    func secrets() {
        #expect(throws: LocalRPC.CommandError(.invalidActivitySecret, "secrets cannot match the party id")) {
            try request(#"{"pid":1,"activity":{"party":{"id":"same"},"secrets":{"join":"same"}}}"#)
        }
        #expect(throws: LocalRPC.CommandError(.invalidActivitySecret, "secrets must be unique")) {
            try request(#"{"pid":1,"activity":{"secrets":{"join":"aa","match":"aa"}}}"#)
        }
        #expect(throws: LocalRPC.CommandError(.invalidActivitySecret, "secrets cannot currently be sent with buttons")) {
            try request(#"{"pid":1,"activity":{"secrets":{"join":"aa"},"buttons":[{"label":"b","url":"https://b.co"}]}}"#)
        }
    }

    @Test("An IPC socket must name its process; a null activity clears")
    func pidAndClear() throws {
        #expect(throws: LocalRPC.CommandError(.invalidCommand, "nonzero pid required")) {
            try request(#"{"activity":null}"#)
        }
        let cleared = try request(#"{"pid":0,"activity":null}"#)
        #expect(cleared.pid == 0)
        #expect(cleared.activity == nil)
        #expect(try request(#"{"activity":{"state":"ok!"}}"#, requiresPID: false).activity != nil)
    }

    @Test("A schema failure is Discord's invalid payload, with Joi's words")
    func invalidPayload() {
        #expect(throws: LocalRPC.CommandError(.invalidPayload, #"child "activity" fails because [child "state" fails because ["state" length must be at least 2 characters long]]"#)) {
            try request(#"{"pid":1,"activity":{"state":"x"}}"#)
        }
    }

    /// `fetchAssetIds` by position: what resolved is kept, the rest dropped.
    @Test("Pictures take what they resolved to, and lose what did not")
    func assets() throws {
        let made = try request(#"{"pid":1,"activity":{"assets":{"large_image":"map","small_image":"rank","large_text":"Dust II"}}}"#)
        #expect(made.largeImage == "map")
        #expect(made.smallImage == "rank")
        let resolved = try #require(made.resolvingAssets(large: "1234", small: nil))
        #expect(resolved.assets?.largeImage == "1234")
        #expect(resolved.assets?.smallImage == nil)
        #expect(resolved.assets?.largeText == "Dust II")
    }

    @Test("The written length JavaScript gives a number")
    func javaScriptLength() {
        #expect(LocalRPCActivityRequest.javaScriptLength(of: 1_700_000_000) == 10)
        #expect(LocalRPCActivityRequest.javaScriptLength(of: 1_700_000_000.5) == 12)
        #expect(LocalRPCActivityRequest.javaScriptLength(of: -5) == 2)
    }
}
